/**
 * The browser's own document for Observable Plot to draw into, where a real one exists. Chosen
 * by the `browser` condition of the `#document` import in package.json, which drops linkedom
 * from client bundles. Runtimes that set that condition without having a document (some Worker
 * bundlers do) are listed before it in package.json and get the server version; if one slips
 * through, this says so rather than failing inside Plot.
 */
export function createDocument(): Document {
  const real = (globalThis as { document?: Document }).document;
  if (!real?.implementation) {
    throw new Error(
      "Enarratio's browser build needs a document, and this runtime has none. Bundle for the server " +
        "(without the 'browser' condition) so Enarratio can use linkedom.",
    );
  }
  return real.implementation.createHTMLDocument("");
}

src/render/figure.ts.source:
/**
 * The figure every chart is delivered in: an optional title, a legend, the SVG named by its text
 * alternative, an optional caption and a data table. The accessible name lives on the SVG, never
 * on the figure, because `role="img"` hides its descendants: naming the figure would hide the
 * caption and table from the readers they exist for.
 */

import { element, escapeHtml } from "../html.js";

/** A color for one series: any CSS color, or a pair for light and dark. */
export type SeriesColor = string | { readonly light: string; readonly dark: string };

/** Options every chart accepts. */
export interface FigureOptions {
  /**
   * Required. What the chart shows, including its finding, written for someone who cannot see
   * it: "Publications rose from 2 in 2015 to 11 in 2024", not "Bar chart of publications".
   */
  readonly alt: string;
  /** A visible title above the chart. */
  readonly title?: string;
  /** A visible caption below the chart: method, source, caveats. */
  readonly caption?: string;
  /** An `id` for the figure, which enhancement events carry as `chartId`. */
  readonly id?: string;
  /** The drawing's width in CSS pixels; the SVG scales down to fit narrower containers. */
  readonly width?: number;
  /** The drawing's height in CSS pixels. */
  readonly height?: number;
  /**
   * How the equivalent data table is shown: in a closed disclosure (default), or only to
   * assistive technology. It is always present.
   */
  readonly dataTable?: "details" | "visually-hidden";
}

/** A scale as the enhancement layer needs it to turn a pointer position back into data. */
export interface ScaleDescription {
  readonly type: string;
  readonly domain: readonly (number | string)[];
  readonly range: readonly number[];
}

/** A table of the values a chart draws. The first column holds row headers. */
export interface DataTable {
  readonly columns: readonly string[];
  readonly rows: readonly (readonly string[])[];
}

/** One legend entry. */
export interface LegendItem {
  readonly label: string;
  /** The palette slot, 1 to 8. */
  readonly slot: number;
}

/** One step of a sequential color legend. */
export interface RampItem {
  readonly label: string;
  /** The ramp step, 1 to 5. */
  readonly step: number;
}

/** Everything a chart hands to {@link figure}. */
export interface FigureParts {
  readonly kind: string;
  readonly svg: string;
  readonly table: DataTable;
  readonly legend?: readonly LegendItem[];
  /** A legend for a sequential ramp (heatmaps, maps), shown instead of a series legend. */
  readonly ramp?: readonly RampItem[];
  /** The data field series come from, which legend filters report. */
  readonly seriesField?: string;
  readonly x?: ScaleDescription;
  /** Which way bars run, for the entrance animation. */
  readonly orientation?: "vertical" | "horizontal";
  /** Per-figure overrides of palette slots, as CSS custom property declarations. */
  readonly slotColors?: ReadonlyMap<number, SeriesColor>;
}

/**
 * Checks the options every chart shares before anything is drawn: a meaningful `alt`, and a
 * positive finite width and height when given (A7, F15).
 */
export function validateFigure(kind: string, options: FigureOptions): void {
  requireAlt(options.alt, kind);
  for (const name of ["width", "height"] as const) {
    const value = options[name];
    if (value !== undefined && !(Number.isFinite(value) && value > 0)) {
      throw new Error(`${kind}: ${name} must be a positive number, is ${value}`);
    }
  }
}

/** Throws unless `alt` is meaningful text. */
function requireAlt(alt: string | undefined, kind: string): string {
  const trimmed = (alt ?? "").trim();
  if (trimmed === "") {
    throw new Error(`${kind}: alt is required and must describe what the chart shows`);
  }
  return trimmed;
}

/** What a caller-supplied color may contain: enough for hex, color functions and var(), not url(). */
const SAFE_COLOR = /^[#a-z0-9(),.%\s-]+$/i;

function cssColor(value: string): string {
  if (!SAFE_COLOR.test(value) || /url\s*\(/i.test(value)) {
    throw new Error(`"${value}" is not an allowed color; use hex, a color function or var(--name)`);
  }
  return value;
}

/** Per-figure palette overrides as an inline style value, or undefined when there are none. */
export function slotStyle(
  colors: ReadonlyMap<number, SeriesColor> | undefined,
): string | undefined {
  if (!colors || colors.size === 0) return undefined;
  return [...colors]
    .map(([slot, color]) => {
      const value =
        typeof color === "string"
          ? cssColor(color)
          : `light-dark(${cssColor(color.light)}, ${cssColor(color.dark)})`;
      return `--enarratio-series-${slot}: ${value}`;
    })
    .join("; ");
}

function tableMarkup(table: DataTable, caption: string): string {
  const head = element(
    "tr",
    {},
    table.columns.map((c) => element("th", { scope: "col" }, escapeHtml(c))).join(""),
  );
  const body = table.rows
    .map((row) =>
      element(
        "tr",
        {},
        row
          .map((cell, i) =>
            i === 0
              ? element("th", { scope: "row" }, escapeHtml(cell))
              : element("td", {}, escapeHtml(cell)),
          )
          .join(""),
      ),
    )
    .join("");
  return element(
    "table",
    {},
    `${element("caption", { class: "enarratio-visually-hidden" }, escapeHtml(caption))}${element("thead", {}, head)}${element("tbody", {}, body)}`,
  );
}

/**
 * A data table as the markup a figure carries: in a closed disclosure (default), or visible only
 * to assistive technology. `caption` names the table for screen readers.
 */
export function dataTableBlock(
  table: DataTable,
  caption: string,
  display: "details" | "visually-hidden" = "details",
): string {
  const markup = tableMarkup(table, caption);
  return display === "visually-hidden"
    ? element("div", { class: "enarratio-data enarratio-visually-hidden" }, markup)
    : element(
        "details",
        { class: "enarratio-data" },
        `${element("summary", {}, "Data table")}${markup}`,
      );
}

function legendMarkup(parts: FigureParts): string {
  const swatch = element("span", { class: "enarratio-swatch", "aria-hidden": "true" });
  if (parts.ramp && parts.ramp.length > 0) {
    return element(
      "ul",
      { class: "enarratio-legend enarratio-ramp" },
      parts.ramp
        .map((item) =>
          element("li", { "data-step": item.step }, `${swatch}${escapeHtml(item.label)}`),
        )
        .join(""),
    );
  }
  if (!parts.legend || parts.legend.length === 0) return "";
  return element(
    "ul",
    { class: "enarratio-legend" },
    parts.legend
      .map((item) =>
        element(
          "li",
          { "data-enarratio-series": item.label, "data-slot": item.slot },
          `${swatch}${escapeHtml(item.label)}`,
        ),
      )
      .join(""),
  );
}

/** Assembles the figure markup for a chart. */
export function figure(options: FigureOptions, parts: FigureParts): string {
  const alt = requireAlt(options.alt, parts.kind);
  const title = options.title?.trim();
  const caption = options.caption?.trim();

  const legend = legendMarkup(parts);
  const tableBlock = dataTableBlock(parts.table, `Data for: ${title ?? alt}`, options.dataTable);

  return element(
    "figure",
    {
      class: "enarratio",
      id: options.id,
      "data-enarratio": parts.kind,
      "data-enarratio-orientation": parts.orientation,
      "data-enarratio-x-scale": parts.x ? JSON.stringify(parts.x) : undefined,
      "data-enarratio-series-field": parts.seriesField,
      style: slotStyle(parts.slotColors),
    },
    [
      title ? element("p", { class: "enarratio-title" }, escapeHtml(title)) : "",
      legend,
      // A frame that scrolls sideways on narrow screens instead of shrinking the text (A13).
      // Drawings 30rem or wider keep that width and scroll; narrower ones scale as usual.
      element(
        "div",
        {
          class:
            (options.width ?? 640) >= 480
              ? "enarratio-frame enarratio-frame-wide"
              : "enarratio-frame",
        },
        parts.svg,
      ),
      caption ? element("figcaption", { class: "enarratio-caption" }, escapeHtml(caption)) : "",
      tableBlock,
    ].join(""),
  );
}

src/render/plot.ts.source:
/**
 * Runs Observable Plot on the server and turns its SVG into Enarratio markup: no inline styles,
 * no per-chart `<style>`, marks named by `data-enarratio-mark`, every drawn datum keyed so the
 * enhancement layer can find it, and coordinates rounded so output is stable across engines.
 */

import * as Plot from "@observablehq/plot";
import { createDocument } from "#document";
import { escapeHtml } from "../html.js";
import type { ScaleDescription } from "./figure.js";

/** What the enhancement layer needs to know about one drawn datum. */
export interface MarkDatum {
  /** Unique within the chart and stable across re-renders of the same data (for transitions). */
  readonly key: string;
  /** The value a click filters on, and the name of the field it belongs to. */
  readonly filter?: { readonly field: string; readonly value: string };
  /** The x value as text, for brush and hover. */
  readonly x?: string;
  /** The series name, when the chart has series. */
  readonly series?: string;
  /**
   * The mark's place for keyboard reading order: its category (column) and its position within
   * the category (row). Taken from the data, not the drawing, so order is right in facets and in
   * charts enhanced while hidden (F9).
   */
  readonly column?: number;
  readonly row?: number;
}

/**
 * A Plot render transform that calls `apply` on each element a mark draws with the datum it
 * draws. Plot draws one element per index entry, in index order, for bar, dot, cell, rect and text.
 */
export function decorate<T>(
  items: readonly T[],
  apply: (el: Element, item: T) => void,
): Plot.RenderFunction {
  return (index, scales, values, dimensions, context, next) => {
    if (!next) throw new Error("decorate() must be used as a render transform");
    const group = next(index, scales, values, dimensions, context);
    if (!group) return group;
    const children = [...group.children];
    if (children.length !== index.length) {
      throw new Error(`a decorated mark drew ${children.length} elements for ${index.length} data`);
    }
    children.forEach((child, i) => {
      const item = items[index[i] as number];
      if (item === undefined) throw new Error(`decorated mark index ${index[i]} has no datum`);
      apply(child, item);
    });
    return group;
  };
}

/**
 * A render transform that tags each element with its datum's keys for the enhancement layer, and
 * optionally decorates it further.
 */
export function keyed<T>(
  items: readonly T[],
  describe: (item: T) => MarkDatum,
  also?: (el: Element, item: T) => void,
): Plot.RenderFunction {
  return decorate(items, (el, item) => {
    tag(el, describe(item));
    also?.(el, item);
  });
}

/** Writes a datum's keys onto an element. */
export function tag(el: Element, datum: MarkDatum): void {
  el.setAttribute("data-enarratio-key", datum.key);
  if (datum.filter) {
    el.setAttribute("data-enarratio-field", datum.filter.field);
    el.setAttribute("data-enarratio-value", datum.filter.value);
  }
  if (datum.x !== undefined) el.setAttribute("data-enarratio-x", datum.x);
  if (datum.series !== undefined) el.setAttribute("data-enarratio-series", datum.series);
  if (datum.column !== undefined) el.setAttribute("data-enarratio-col", String(datum.column));
  if (datum.row !== undefined) el.setAttribute("data-enarratio-row", String(datum.row));
}

const NUMBER = /-?\d+\.\d{3,}(?:e-?\d+)?/g;
const ROUNDED_ATTRIBUTES = new Set([
  "x",
  "y",
  "x1",
  "x2",
  "y1",
  "y2",
  "cx",
  "cy",
  "r",
  "width",
  "height",
  "d",
  "points",
  "transform",
  "viewBox",
]);

function roundCoordinates(root: Element): void {
  for (const el of [root, ...root.querySelectorAll("*")]) {
    for (const name of el.getAttributeNames()) {
      if (!ROUNDED_ATTRIBUTES.has(name)) continue;
      const value = el.getAttribute(name);
      if (value === null) continue;
      el.setAttribute(
        name,
        value.replace(NUMBER, (n) => String(Math.round(Number(n) * 100) / 100)),
      );
    }
  }
}

const ELEMENT_NODE = 1;
const TEXT_NODE = 3;

/**
 * Serializes an SVG tree with every attribute and text node escaped, so the markup is valid in
 * HTML and XML alike whatever the data contains. Childless elements self-close, as SVG allows.
 */
function serialize(node: Node): string {
  if (node.nodeType === TEXT_NODE) return escapeHtml(node.textContent ?? "");
  if (node.nodeType !== ELEMENT_NODE) return "";
  const el = node as Element;
  const attrs = el
    .getAttributeNames()
    .map((name) => ` ${name}="${escapeHtml(el.getAttribute(name) ?? "")}"`)
    .join("");
  const children = [...el.childNodes].map(serialize).join("");
  return children === ""
    ? `<${el.localName}${attrs}/>`
    : `<${el.localName}${attrs}>${children}</${el.localName}>`;
}

/** The result of {@link renderPlot}. */
export interface RenderedPlot {
  readonly svg: string;
  readonly x?: ScaleDescription;
}

/**
 * Draws a Plot specification into SVG markup named by `alt`: one image, or a group when its
 * marks are links. Throws if Plot warns, because a warning means the chart shown would not be the
 * chart intended.
 */
export function renderPlot(
  options: Plot.PlotOptions,
  alt: string,
  role: "img" | "group" = "img",
  after?: (svg: SVGSVGElement) => void,
): RenderedPlot {
  const document = createDocument();
  const svg = Plot.plot({ ...options, document }) as unknown as SVGSVGElement & Plot.Plot;

  // Plot's warning is its own node: a top-level <text> whose <title> counts the warnings. Found by
  // that structure, not by the glyph, which data may contain (F13).
  const warning = [...svg.children].find(
    (el) =>
      el.localName === "text" &&
      /^\d+ warnings?\. Please check the console\.$/.test(
        el.querySelector("title")?.textContent ?? "",
      ),
  );
  if (warning) {
    throw new Error(
      `Observable Plot warned while drawing "${alt}": ${warning.querySelector("title")?.textContent ?? ""}`,
    );
  }
  if (svg.localName !== "svg") {
    throw new Error(
      "Enarratio charts must draw a single SVG; remove Plot options that add a legend or caption",
    );
  }

  for (const style of svg.querySelectorAll("style")) style.remove();
  for (const name of ["class", "font-family", "font-size", "style"]) svg.removeAttribute(name);
  // Plot names groups with aria-label, which is invalid on a <g> without a role and hidden anyway
  // inside role="img". The name moves to a data attribute for CSS and the enhancement layer.
  for (const group of svg.querySelectorAll("[aria-label]")) {
    group.setAttribute("data-enarratio-mark", group.getAttribute("aria-label") ?? "");
    group.removeAttribute("aria-label");
    // Axes repeat what the text alternative and the data table say; once enhanced, loose tick
    // text would be read before the marks (A12).
    if (/axis/.test(group.getAttribute("data-enarratio-mark") ?? "")) {
      group.setAttribute("aria-hidden", "true");
    }
  }
  after?.(svg);
  roundCoordinates(svg);
  // A chart whose marks are links cannot be one image: role="img" would hide the links.
  svg.setAttribute("role", role);
  if (role === "group") svg.setAttribute("aria-roledescription", "chart");
  svg.setAttribute("aria-label", alt);

  let x: ScaleDescription | undefined;
  const scale = svg.scale("x");
  if (scale?.domain && scale.range && scale.type) {
    x = {
      type: scale.type,
      domain: [...scale.domain].map((d) =>
        d instanceof Date ? d.getTime() : (d as number | string),
      ),
      range: [...scale.range] as number[],
    };
  }
  const markup = serialize(svg);
  return x ? { svg: markup, x } : { svg: markup };
}

